    if (modeIn < 1.0) { return 0.0; }
    var mode = modeIn;
    var depth = clipZ;
    if (mode >= 8.5) { mode = mode - 8.0; depth = eyeDistance; }
    else if (mode >= 4.5) { mode = mode - 4.0; depth = eyeDepth; }
